                                                            }}

                                                        />

                                                        {isSelected && <div className="checkmark"><i className="fas fa-check-circle"></i></div>}

                                                    </div>

                                                    <span className="spell-name-lbl">{spell.name}</span>

                                                </div>

                                            );

                                        })}

                                    </div>

