                onMouseLeave={handleMouseLeave}
                onMouseMove={handleMouseMove}
                onClick={handleClick}
                style={{ cursor: isGMMode ? 'pointer' : 'default' }}
            >
                {renderResourceDisplay()}
                {!hasDedicatedBar && (
                    <ResourceTooltip
                        finalConfig={finalConfig}
                        modifiedConfig={modifiedConfig}
