                        boundDemons={boundDemons}
                        selectedDemonIndex={selectedDemonIndex}
                        localDominanceDie={localDominanceDie}
                        localMadness={localMadness ?? finalClassResource?.current ?? 0}
                        getDangerLevel={getDangerLevel}
                        getNextThreshold={getNextThreshold}
                        localThreads={localThreads}
                        getThreadLevel={getThreadLevel}
                        selectedFateWeaverSpec={selectedFateWeaverSpec}
                        localFortunePoints={localFortunePoints}
                        localQuarryMarks={localQuarryMarks}
                        companionHP={companionHP}
                        companionMaxHP={companionMaxHP}
                        phylacteryHoverSection={phylacteryHoverSection}
                        lichborneSpec={lichborneSpec}
                        localPhylacteryHP={localPhylacteryHP}
                        currentLunarPhase={currentLunarPhase}
                        roundsInPhase={roundsInPhase}
                        lunarchSpec={lunarchSpec}
                        localNotes={localNotes}
                        visionsHoverSection={visionsHoverSection}
                        oracleSpec={oracleSpec}
                        localVisions={localVisions}
                        berserkerRage={berserkerRage}
                    />
                )}
            </div>

        </>
    );
};

export default React.memo(ClassResourceBar);

/**



 * Level-Up Choice Modal



 *



 * Displays when a character levels up with a point-spending system:



 * - 2 points to spend



 * - Each choice costs 1 point:



 *   - +1 to any attribute (can pick same attribute multiple times)



 *   - +15 Maximum Health



 *   - +10 Maximum Mana



 * - All classes: Also learn 1 spell from available options (free, doesn't cost points)



 */







import React, { useState, useMemo, useEffect } from 'react';



import { createPortal } from 'react-dom';



import { getSafePortalTarget } from '../../utils/portalUtils';







// Import all class data



import { ARCANONEER_DATA } from '../../data/classes/arcanoneerData';



import { BERSERKER_DATA } from '../../data/classes/berserkerData';





import { HARBINGER_DATA } from '../../data/classes/harbingerData';



import { CHRONARCH_DATA } from '../../data/classes/chronarchData';



import { INQUISITOR_DATA } from '../../data/classes/inquisitorData';



// 'Deathcaller' and 'Lichborne' merged into Revenant as Phase 1.10 consolidation

import { REVENANT_DATA } from '../../data/classes/revenantData';



// 'Dreadnaught' removed (absorbed into Martyr as Ironclad specialization)







import { FALSE_PROPHET_DATA } from '../../data/classes/falseProphetData';



import { GAMBIT_DATA } from '../../data/classes/gambitData';





import { APEX_DATA } from '../../data/classes/apexData';



