                                        {/* Compact current selections (chips) for quick review and adjustment */}
                    {choices.length > 0 && (
                        <div className="current-choices compact" style={{
                            display: 'flex',
                            flexWrap: 'wrap',
                            gap: '8px',
                            marginBottom: '10px'
                        }}>
                            {choices.map((choice, index) => (
                                <div
                                    key={index}
                                    className="choice-chip"
                                    style={{
                                        display: 'inline-flex',
                                        alignItems: 'center',
                                        gap: '6px',
                                        padding: '4px 10px',
                                        background: 'var(--my-parchment-light)',
                                        border: '1px solid var(--my-brown-medium)',
                                        borderRadius: '14px',
                                        fontSize: '12px'
                                    }}
                                >
                                    <span>
                                        {choice.type === 'health' && '+15 Max Health'}
                                        {choice.type === 'mana' && '+10 Max Mana'}
