                                        return (



                                            <button



                                                key={attr}



                                                className={`choice-btn attribute ${count > 0 ? 'selected' : ''}`}



                                                onClick={() => addChoice('attribute', attr)}



                                                style={{ position: 'relative' }}



                                                disabled={pointsRemaining === 0}



                                            >



                                                <span>+1 {attr.charAt(0).toUpperCase() + attr.slice(1)}</span>



                                                {count > 0 && (



                                                    <>



                                                        <span



                                                            aria-hidden="true"



                                                            style={{



                                                                position: 'absolute',



                                                                top: 0,



                                                                right: 0,



                                                                width: 0,



                                                                height: 0,



                                                                borderTop: '18px solid var(--my-green)',



                                                                borderLeft: '18px solid transparent'



                                                            }}



                                                        />



                                                        <span



                                                            aria-hidden="true"



                                                            style={{



                                                                position: 'absolute',



                                                                top: 1,



                                                                right: 2,



                                                                color: '#fff',



                                                                fontSize: '12px',



                                                                fontWeight: 700



                                                            }}



                                                        >



                                                            ✓{count > 1 ? `x${count}` : ''}



                                                        </span>



                                                    </>



                                                )}



                                            </button>



                                        );



                                    })}



                                </div>



                            </div>



                        </div>



                </div>







                {/* Action Buttons */}



                <div className="level-up-actions">



                    <button



                        className="confirm-btn"



                        onClick={handleConfirm}



                        disabled={!canConfirm()}



                    >



                        <i className="fas fa-check"></i> Confirm Choice



                    </button>



                </div>



            </div>



        </div>,



        portalTarget



    );







    const spellPopup = clickedSpell && createPortal(



        <div



            className="level-up-spell-popup-overlay"



            onClick={() => setClickedSpell(null)}



        >



            <button



                className="level-up-spell-popup-nav level-up-spell-popup-nav-prev"



                onClick={(e) => { e.stopPropagation(); navigateClickedSpell(-1); }}



                disabled={clickedSpellIndex <= 0}



                aria-label="Previous spell"



            >



                <i className="fas fa-chevron-left"></i>



            </button>



            <div



                className="level-up-spell-popup-content"



