 // Render specializations tab
 const renderSpecializations = () => {
  const { specializations } = classData;

  if (!specializations || !specializations.specs) {
   return (
    <div className="class-detail-section parchment-content">
     <p className="guide-empty-text">No specialization data available for this tradition.</p>
    </div>
   );
  }

  const specs = specializations.specs;
  const activeSpecIndex = Math.min(Math.max(selectedSpecTreeIndex, 0), specs.length - 1);
  const activeSpec = specs[activeSpecIndex] || specs[0];
  const methodChips = typeof activeSpec?.playstyle === 'string'
   ? activeSpec.playstyle.split(',').map(part => part.trim().replace(/\.$/, '')).filter(Boolean)
   : [];
  const showMethodChips = methodChips.length >= 2 && methodChips.every(chip => chip.length <= 48);

  return (
    <div className="class-detail-section parchment-content class-specializations-section">
     <div className="guide-badge-header spec-main-header">
     <div>
      <span className="guide-badge">
       <i className="fas fa-medal"></i> SPECIALIZATIONS & TALENT TREES
      </span>
      <h3>{specializations.title}</h3>
     </div>

     <div className="spec-view-mode-toggle">
      <button
       type="button"
       className={`spec-mode-btn ${specViewMode === 'overview' ? 'active' : ''}`}
       onClick={() => setSpecViewMode('overview')}
      >
        <i className="fas fa-id-card" aria-hidden="true"></i> Overview
      </button>
      <button
       type="button"
       className={`spec-mode-btn ${specViewMode === 'talent-tree' ? 'active' : ''}`}
       onClick={() => setSpecViewMode('talent-tree')}
      >
        <i className="fas fa-sitemap" aria-hidden="true"></i> Talent trees
      </button>
     </div>
    </div>

    {specViewMode === 'overview' ? (
     <>
      {specializations.subtitle && (
       <div className="guide-subtitle">{specializations.subtitle}</div>
      )}

      <div className="guide-description">
       {renderContent(specializations.description)}
      </div>

      {specializations.passiveAbility && (
       <div className="shared-passive-card">
        <div className="shared-passive-badge">
         <i className="fas fa-star"></i> SHARED PASSIVE
        </div>
        <div className="shared-passive-content">
         <strong>{specializations.passiveAbility.name}</strong>
         <p>{specializations.passiveAbility.description}</p>
        </div>
       </div>
      )}

      {activeSpec && (
       <div className="spec-spotlight">
        <div className="spec-selector-row" role="tablist" aria-label="Choose a specialization">
         {specs.map((spec, idx) => (
          <button
           key={spec.id || idx}
           type="button"
           role="tab"
           aria-selected={idx === activeSpecIndex}
           className={`spec-selector-card ${idx === activeSpecIndex ? 'active' : ''}`}
           style={{ '--spec-color': spec.color }}
           onClick={() => setSelectedSpecTreeIndex(idx)}
          >
           <span className="spec-selector-icon">
            <img
             src={getIconUrl(spec.icon, 'abilities')}
             alt=""
             onError={(e) => {
              e.target.onerror = null;
              e.target.src = getIconUrl('Utility/Utility', 'abilities');
             }}
            />
           </span>
           <span className="spec-selector-text">
            <span className="spec-selector-name">{spec.name}</span>
            <span className="spec-selector-theme">{spec.theme}</span>
           </span>
           <i className="fas fa-check-circle spec-selector-check"></i>
          </button>
         ))}
        </div>

        <div className="spec-profile" role="tabpanel" style={{ '--spec-color': activeSpec.color }}>
         <div className="spec-profile-header" style={{ backgroundColor: activeSpec.color }}>
          <div className="spec-icon">
           <img
            src={getIconUrl(activeSpec.icon, 'abilities')}
            alt={activeSpec.name}
            onError={(e) => {
             e.target.onerror = null;
             e.target.src = getIconUrl('Utility/Utility', 'abilities');
            }}
           />
          </div>
          <div className="spec-title">
           <h4>{activeSpec.name}</h4>
           <p className="spec-theme">{activeSpec.theme}</p>
          </div>
         </div>

         <div className="spec-body premium-body">
          <p className="spec-description">{parseTextWithLoreLinks(activeSpec.description)}</p>

          {showMethodChips ? (
           <div className="spec-method">
            <span className="spec-method-label"><i className="fas fa-crosshairs"></i> Combat Method</span>
            <div className="spec-method-chips">
             {methodChips.map((chip, i) => (
              <span key={i} className="spec-method-chip">{chip}</span>
             ))}
            </div>
           </div>
          ) : (
           <div className="spec-playstyle">
            <strong>Combat Method:</strong> {activeSpec.playstyle}
           </div>
          )}

          <div className="spec-traits-grid">
           {activeSpec.strengths && activeSpec.strengths.length > 0 && (
            <div className="spec-strengths">
             <h5><i className="fas fa-plus-circle"></i> Strengths</h5>
             <ul>
              {activeSpec.strengths.map((strength, i) => (
               <li key={i}>{parseTextWithLoreLinks(strength)}</li>
              ))}
             </ul>
            </div>
           )}

           {activeSpec.weaknesses && activeSpec.weaknesses.length > 0 && (
            <div className="spec-weaknesses">
             <h5><i className="fas fa-minus-circle"></i> Weaknesses</h5>
             <ul>
              {activeSpec.weaknesses.map((weakness, i) => (
               <li key={i}>{parseTextWithLoreLinks(weakness)}</li>
              ))}
             </ul>
            </div>
           )}
          </div>

          {activeSpec.keyAbilities && (
           <div className="spec-key-abilities">
            <h5><i className="fas fa-bolt"></i> Key Abilities</h5>
            <ul>
             {activeSpec.keyAbilities.map((ability, i) => (
              <li key={i}>
               {typeof ability === 'string' ? ability : (
                <>
                 <strong>{ability.name}</strong>
                 {ability.type && <span> ({ability.type})</span>}
                 {ability.cost && <span> - {ability.cost}</span>}
                 {ability.description && <span>: {ability.description}</span>}
                </>
               )}
              </li>
             ))}
            </ul>
           </div>
          )}

          {(activeSpec.passiveAbilities || activeSpec.passiveAbility || activeSpec.specPassive) && (
           <div className="spec-passives">
            <h5><i className="fas fa-star"></i> Passive Abilities</h5>

            {activeSpec.passiveAbilities && activeSpec.passiveAbilities.map((passive, i) => (
             <div key={i} className={`passive-ability ${passive.tier === 'Path Passive' ? 'shared' : 'unique'}`}>
              <div className="passive-header">
               <strong>{passive.name}</strong>
               <span className="passive-tier">{passive.tier}</span>
              </div>
              <p className="passive-description">{passive.description}</p>
              {passive.sharedBy && (
               <p className="passive-note"><em>Shared by: {passive.sharedBy}</em></p>
              )}
              {passive.uniqueTo && (
               <p className="passive-note"><em>Unique to: {passive.uniqueTo}</em></p>
              )}
             </div>
            ))}

            {activeSpec.passiveAbility && (
             <div className="passive-ability shared">
              <div className="passive-header">
               <strong>{activeSpec.passiveAbility.name}</strong>
               <span className="passive-tier">Path Passive</span>
              </div>
              <p className="passive-description">{activeSpec.passiveAbility.description}</p>
             </div>
            )}

            {activeSpec.specPassive && (
             <div className="passive-ability unique">
              <div className="passive-header">
               <strong>{activeSpec.specPassive.name}</strong>
               <span className="passive-tier">Specialization Passive</span>
              </div>
              <p className="passive-description">{activeSpec.specPassive.description}</p>
             </div>
            )}
           </div>
          )}

          {activeSpec.recommendedFor && (
           <div className="spec-recommendation">
            <i className="fas fa-thumbs-up"></i> <strong>Recommended for:</strong> {activeSpec.recommendedFor}
           </div>
          )}

          <div className="spec-card-actions">
           <button
            type="button"
            className="spec-view-tree-btn"
            onClick={() => {
             setSelectedSpecTreeIndex(activeSpecIndex);
             setSpecViewMode('talent-tree');
            }}
            style={{ '--spec-btn-color': activeSpec.color }}
           >
            <i className="fas fa-sitemap"></i> View {activeSpec.name} Talent Tree
           </button>
          </div>
         </div>
        </div>
       </div>
      )}
     </>
    ) : (
     <div className="spec-talent-tree-section">
      <div className="spec-tree-toolbar">
       <button
        type="button"
        className="spec-back-to-cards-btn"
        onClick={() => setSpecViewMode('overview')}
       >
        <i className="fas fa-arrow-left"></i> Back to Overview
       </button>

       <div className="spec-tree-nav-pills">
        {specializations.specs.map((spec, idx) => (
         <button
          key={spec.id || idx}
          type="button"
          className={`spec-nav-pill ${selectedSpecTreeIndex === idx ? 'active' : ''}`}
          onClick={() => setSelectedSpecTreeIndex(idx)}
          style={{ '--spec-accent': spec.color || '#d4af37' }}
         >
          <img
           src={getIconUrl(spec.icon, 'abilities')}
           alt=""
           className="spec-nav-pill-icon"
           onError={(e) => {
            e.target.onerror = null;
            e.target.src = getIconUrl('Utility/Utility', 'abilities');
           }}
          />
          <span>{spec.name}</span>
         </button>
        ))}
        <button
         type="button"
         className={`spec-nav-pill summary-pill ${selectedSpecTreeIndex === specializations.specs.length ? 'active' : ''}`}
         onClick={() => setSelectedSpecTreeIndex(specializations.specs.length)}
        >
         <i className="fas fa-book-bookmark"></i>
         <span>Mastery Grimoire</span>
        </button>
       </div>
      </div>

      <div className="spec-talent-tree-container">
       <TalentTreeContent
        customClass={classData.name}
        selectedTreeIndex={selectedSpecTreeIndex}
        onTreeSelect={setSelectedSpecTreeIndex}
        readOnly={true}
       />
      </div>
     </div>
    )}
   </div>
  );
 };



 // Render spells tab
 const renderSpells = () => {
  const spells = processedSpells;

  if (!spells || spells.length === 0) {
   return (
    <div className="class-detail-section">
     <p>No spells available for this tradition yet.</p>
    </div>
   );
  }

  // Get class-specific icon
  const classIcons = {
   'pyrofiend': 'fas fa-fire',
   'minstrel': 'fas fa-music',
   'gambit': 'fas fa-dice',
   'chaos-weaver': 'fas fa-dice',
   'martyr': 'fas fa-heart',
   'chronarch': 'fas fa-clock',
   'fate-weaver': 'fas fa-cards',
   // REMOVED: lichborne icon merged into Revenant as Phase 1.10 consolidation
   // 'lichborne': 'fas fa-snowflake',
   'animist': 'fas fa-wind',
   'inquisitor': 'fas fa-gavel',
   'arcanoneer': 'fas fa-atom',
   'revenant': 'fas fa-skull-crossbones',
   'spellguard': 'fas fa-shield-alt',

   'false-prophet': 'fas fa-eye',
   'false_prophet': 'fas fa-eye',
   'plaguebringer': 'fas fa-biohazard',
   'shaper': 'fas fa-yin-yang',
   'berserker': 'fas fa-axe-battle',
   // 'bladedancer' removed (consolidated into Shaper)
   // 'dreadnaught' removed (absorbed into Martyr as Ironclad specialization)
   // 'titan' removed (absorbed into Warden as Monolith specialization)
   'toxicologist': 'fas fa-flask',
   'lunarch': 'fas fa-moon',
   'apex': 'fas fa-crosshairs',
   'Warden': 'fas fa-gavel',
   'augur': 'fas fa-skull-crossbones',
   'crusader': 'fas fa-cross'
  };

  let categoryIcon = classIcons[classData.id] || 'fas fa-magic';

  // Universal level-based grouping for ALL classes (Level 1-10)
  let spellsByCategory = {
   'Level 1': spells.filter(s => s.level === 1),
   'Level 2': spells.filter(s => s.level === 2),
   'Level 3': spells.filter(s => s.level === 3),
   'Level 4': spells.filter(s => s.level === 4),
   'Level 5': spells.filter(s => s.level === 5),
   'Level 6': spells.filter(s => s.level === 6),
   'Level 7': spells.filter(s => s.level === 7),
   'Level 8': spells.filter(s => s.level === 8),
   'Level 9': spells.filter(s => s.level === 9),
   'Level 10': spells.filter(s => s.level === 10)
  };

  // Split categories into pages (2 categories per page, one on each side)
